<script setup lang="ts">const props=defineProps<{status:string}>();const verified=computed(()=>props.status==="verified");</script>
<template><article class="identity-card" :data-verified="verified"><span aria-hidden="true">{{verified?'✓':'!'}}</span><div><strong>{{verified?'هویت شما تأیید شده است':'تأیید هویت کامل نشده است'}}</strong><p>{{verified?'اعتماد کاربران به آگهی‌های شما بیشتر می‌شود.':'برای امنیت حساب و امکانات مالی، مراحل تأیید را تکمیل کنید.'}}</p></div><NuxtLink v-if="!verified" class="button button-secondary" to="/my/profile#identity">شروع تأیید</NuxtLink></article></template>
